import { mkdir, readFile, stat, writeFile, unlink } from 'node:fs/promises'
import path from 'node:path'
import { env } from '@/lib/env'

/**
 * Report storage boundary.
 *
 * `local` is the default for development and single-host deployments.
 * `supabase` (Supabase Storage / S3-compatible object store) is the durable,
 * multi-instance option required on Vercel: both the web download route and
 * the long-running worker read the same bucket, so a report generated by the
 * worker is downloadable from any web instance.
 *
 * Implement `ReportStorage` to add another provider (S3, R2) without touching
 * the pipeline.
 */
export interface ReportStorage {
  readonly kind: 'local' | 'supabase'
  put(key: string, data: Buffer): Promise<{ key: string; size: number }>
  get(key: string): Promise<Buffer>
  exists(key: string): Promise<boolean>
  remove(key: string): Promise<void>
  /** Local adapter only; remote adapters return null. */
  absolutePath(key: string): string | null
}

const SAFE_KEY = /^[a-zA-Z0-9/_.-]+$/

function assertSafeKey(key: string) {
  if (!SAFE_KEY.test(key) || key.includes('..') || key.startsWith('/') || key.includes('\\')) {
    throw new Error('Unsafe report storage key')
  }
}

function baseDir(): string {
  const configured = env().REPORT_DIR
  return path.isAbsolute(configured) ? configured : path.join(process.cwd(), configured)
}

class LocalReportStorage implements ReportStorage {
  readonly kind = 'local' as const

  absolutePath(key: string): string {
    assertSafeKey(key)
    const base = baseDir()
    const resolved = path.resolve(base, key)
    if (!resolved.startsWith(path.resolve(base))) throw new Error('Unsafe report storage key')
    return resolved
  }

  async put(key: string, data: Buffer) {
    const target = this.absolutePath(key)
    await mkdir(path.dirname(target), { recursive: true })
    await writeFile(target, data)
    return { key, size: data.byteLength }
  }

  async get(key: string) {
    return readFile(this.absolutePath(key))
  }

  async exists(key: string) {
    try {
      const info = await stat(this.absolutePath(key))
      return info.isFile()
    } catch {
      return false
    }
  }

  async remove(key: string) {
    await unlink(this.absolutePath(key)).catch(() => undefined)
  }
}

/**
 * Supabase Storage adapter (service-role key, server-only).
 *
 * Uses the Storage REST API with `fetch` so no extra SDK is bundled into the
 * Next.js server. Keys are validated before they are interpolated into a URL.
 */
class SupabaseReportStorage implements ReportStorage {
  readonly kind = 'supabase' as const
  private readonly endpoint: string
  private readonly auth: string

  constructor(supabaseUrl: string, serviceRoleKey: string, bucket: string) {
    this.endpoint = `${supabaseUrl.replace(/\/$/, '')}/storage/v1/object/${bucket}`
    this.auth = `Bearer ${serviceRoleKey}`
  }

  private url(key: string) {
    assertSafeKey(key)
    return `${this.endpoint}/${key.split('/').map(encodeURIComponent).join('/')}`
  }

  absolutePath(): null {
    return null
  }

  async put(key: string, data: Buffer) {
    const response = await fetch(this.url(key), {
      method: 'POST',
      headers: {
        authorization: this.auth,
        'content-type': 'application/pdf',
        'cache-control': 'max-age=31536000',
        'x-upsert': 'true',
      },
      body: new Uint8Array(data),
    })
    if (!response.ok) {
      throw new Error(`Report upload failed (${response.status}): ${(await response.text()).slice(0, 200)}`)
    }
    return { key, size: data.byteLength }
  }

  async get(key: string) {
    const response = await fetch(this.url(key), { headers: { authorization: this.auth } })
    if (!response.ok) throw new Error(`Report download failed (${response.status})`)
    return Buffer.from(await response.arrayBuffer())
  }

  async exists(key: string) {
    const response = await fetch(this.url(key), { method: 'HEAD', headers: { authorization: this.auth } })
    return response.ok
  }

  async remove(key: string) {
    await fetch(this.url(key), { method: 'DELETE', headers: { authorization: this.auth } }).catch(() => undefined)
  }
}

export function reportStorage(): ReportStorage {
  const config = env()
  if (config.REPORT_STORAGE === 'supabase') {
    if (!config.SUPABASE_URL || !config.SUPABASE_SERVICE_ROLE_KEY) {
      throw new Error(
        'REPORT_STORAGE=supabase requires SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY (server-only).',
      )
    }
    return new SupabaseReportStorage(
      config.SUPABASE_URL,
      config.SUPABASE_SERVICE_ROLE_KEY,
      config.SUPABASE_REPORT_BUCKET,
    )
  }
  return new LocalReportStorage()
}

/** Deterministic, filename-safe key: clients/<clientId>/<auditId>.pdf */
export function reportKeyFor(clientId: string, auditId: string): string {
  const safe = (value: string) => value.replace(/[^a-zA-Z0-9_-]/g, '')
  return `clients/${safe(clientId)}/${safe(auditId)}.pdf`
}

export function downloadFilenameFor(siteUrl: string, auditId: string, generatedAt: Date): string {
  const host = (() => {
    try {
      return new URL(siteUrl).hostname.replace(/^www\./, '')
    } catch {
      return 'website'
    }
  })()
  const date = generatedAt.toISOString().slice(0, 10)
  return `edgelink-seo-audit-${host}-${date}-${auditId.slice(-6)}.pdf`.replace(/[^a-zA-Z0-9.\-]/g, '-')
}
